<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {RefreshCw,LoaderCircle,CheckCircle2,AlertCircle,Database,CalendarClock} from 'lucide-vue-next';
type Item=Record<string,any>;
const props=defineProps<{projects:Item[];request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{updated:[]}>();
const projects=computed(()=>props.projects.filter(p=>String(p.source_ref??'').startsWith('app:')));
const selected=ref('');const report=ref<Item|null>(null);const loading=ref(false);const error=ref('');
const selectedContext=computed(()=>{const project=projects.value.find(p=>p.id===selected.value);return project?JSON.stringify([project.id,project.user_id??null,project.tenant_id??null,project.source_ref]):'';});
let generation=0;
watch(selectedContext,()=>{generation++;report.value=null;error.value='';loading.value=false;if(!selectedContext.value)selected.value='';},{flush:'sync'});
onUnmounted(()=>generation++);
async function inspect(){
 if(!selectedContext.value||loading.value)return;
 const version=++generation;const context=selectedContext.value;const project=selected.value;
 const current=()=>version===generation&&selectedContext.value===context;
 loading.value=true;error.value='';report.value=null;
 try{const result=await props.request('/projects/'+project+'/refresh-coverage');if(current()){report.value=result;emit('updated');}}
 catch(e){if(current())error.value=(e as Error).message;}
 finally{if(current())loading.value=false;}
}
function state(status:string){return ({daily_configured:'Agenda diária identificada',schedule_required:'Agenda diária pendente',publication_required:'Publicação da fonte necessária',metadata_unavailable:'Metadados indisponíveis',observed_success:'Última carga concluída',completed:'Teste concluído',pending:'Execução pendente',running:'Carga em andamento',failed:'Falha na última carga',incomplete:'Carga incompleta',unavailable:'Execução indisponível',inactive:'Agenda inativa',stale:'Última carga há mais de 24 horas',configuration_changed:'Configuração alterada; confira novamente',ambiguous:'Mais de uma execução encontrada; correlação pendente',awaiting_history:'Aguardando execução no histórico'} as Record<string,string>)[status]??status;}
function date(value:string){return new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Sao_Paulo'}).format(new Date(value));}
</script>
<template><section class="refresh-inspector"><div class="inspection-heading"><div><h2><Database :size="19"/>Conferir todas as fontes</h2><p>Escolha o projeto para consultar as agendas e o resultado real das cargas.</p></div></div><div v-if="projects.length" class="inspection-controls"><label>Projeto<select v-model="selected" aria-label="Projeto para conferir atualizações"><option value="">Selecione uma aplicação</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}} · {{p.tenant_name}}</option></select></label><button class="secondary-button" :disabled="!selectedContext||loading" @click="inspect"><LoaderCircle v-if="loading" class="spin" :size="16"/><RefreshCw v-else :size="16"/>{{loading?'Conferindo fontes…':'Verificar atualizações'}}</button></div><p v-else class="inspection-help">Abra uma aplicação pelo Catálogo BI ou crie um dashboard no projeto para conferir suas fontes.</p><div v-if="error" class="form-error" role="alert"><AlertCircle :size="17"/>{{error}}</div><div v-if="report" class="inspection-report"><div class="inspection-summary" :class="{success:report.verified}"><CheckCircle2 v-if="report.verified" :size="20"/><AlertCircle v-else :size="20"/><div><strong>{{report.verified?'Atualização diária verificada':report.configured?(report.last_executions_successful?'Últimas cargas conferidas; teste pendente':'Agenda configurada; execução exige conferência'):'Há fontes pendentes de atualização'}}</strong><p>{{report.sources.length}} fonte(s) identificada(s) · {{report.timezone}}</p></div></div><article v-for="source in report.sources" :key="source.flow_id" class="inspection-source"><div class="inspection-source-title"><strong>{{source.name}}</strong><span :class="{ok:source.configured}">{{state(source.status)}}</span></div><p>{{source.tables.map((t:Item)=>t.name).join(' · ')}}</p><ul><li v-for="schedule in source.schedules" :key="schedule.id"><CalendarClock :size="14"/><span>{{schedule.name}} · {{schedule.configuration_current===false?'Configuração a conferir':schedule.active?'Ativa':'Inativa'}}<small>{{schedule.frequency||'Frequência a conferir'}} · {{schedule.timezone||'Fuso não informado'}}</small></span></li></ul><p v-if="!source.schedules.length" class="inspection-help">Nenhuma agenda acessível encontrada para esta fonte.</p><div v-if="source.last_execution" class="inspection-execution"><CheckCircle2 v-if="['observed_success','completed'].includes(source.last_execution.status)" :size="15"/><AlertCircle v-else :size="15"/><span>{{state(source.last_execution.status)}}<span v-if="source.last_execution.finished_at"> · {{date(source.last_execution.finished_at)}} (Brasília)</span></span></div><p v-if="source.recommendation==='verify_current_configuration'" class="inspection-help">Confira a agenda e use Verificar atualizações novamente. Esta consulta não executa cargas.</p><p v-if="source.recommendation==='request_source_publication'" class="inspection-help">A fonte está privada. A publicação precisa ser autorizada antes de agendar.</p></article><p v-for="(table,index) in report.unresolved_tables" :key="index" class="form-error">{{table.name||(table.table_id?'Tabela #'+table.table_id:'Fonte não identificada')}}: {{table.reason}}</p><p v-if="report.verified" class="inspection-help"><CheckCircle2 :size="15"/> Teste de carga confirmado para a configuração atual de todas as fontes.</p><p class="inspection-help">A conferência preserva agendas existentes mais frequentes. Uma execução sob demanda só será confirmada pelo identificador da carga e pelo sucesso de todas as fontes.</p></div></section></template>
<style scoped>.refresh-inspector{margin:26px 0;padding:22px;background:white;border:1px solid #e1e7f0;border-radius:12px}.inspection-heading h2{display:flex;align-items:center;gap:10px;font-size:16px;color:#243a5d}.inspection-heading p,.inspection-help{font-size:12px;line-height:1.7;color:#748198;margin-top:9px}.inspection-controls{display:flex;align-items:flex-end;gap:12px;margin-top:20px}.inspection-controls label{flex:1;max-width:550px;font-size:11px;color:#61728d}.inspection-controls select{display:block;width:100%;background:white;border:1px solid #dbe2ee;border-radius:7px;padding:10px;margin-top:7px;color:#344b6b}.inspection-report{margin-top:20px}.inspection-summary{display:flex;align-items:center;gap:12px;padding:14px;border-radius:8px;background:#fff6e8;color:#927133}.inspection-summary.success{background:#eef8f4;color:#36795f}.inspection-summary strong{font-size:13px}.inspection-summary p{font-size:11px;margin-top:4px}.inspection-source{border:1px solid #e5eaf2;padding:17px;border-radius:8px;margin-top:12px}.inspection-source-title{display:flex;gap:12px;justify-content:space-between;align-items:center}.inspection-source-title strong{font-size:13px;color:#30496c}.inspection-source-title>span{font-size:10px;color:#9d7837;background:#fff7e7;padding:5px 7px;border-radius:4px}.inspection-source-title>span.ok{color:#398366;background:#ecf7f1}.inspection-source>p{font-size:11px;color:#7d8aa0;margin-top:7px}.inspection-source ul{list-style:none;padding:0;margin:14px 0;display:grid;gap:9px}.inspection-source li{display:flex;gap:8px;font-size:12px;align-items:center;color:#576e8c}.inspection-source small{display:block;color:#8b97aa;font-size:10px;margin-top:5px}.inspection-execution{display:flex;align-items:center;gap:7px;font-size:11px;color:#637c73;margin-top:12px}@media(max-width:700px){.inspection-controls{align-items:stretch;flex-direction:column}.inspection-source-title{align-items:flex-start;flex-direction:column}}</style>
